previewCss:
.darma-loader-darma-b9-lava-lamp { --accent: var(--loader-color, #f97316); --accent-2: var(--loader-secondary-color, #e11d48); width: calc(var(--loader-size, 100px) * .62); height: var(--loader-size, 100px); border-radius: calc(var(--loader-size, 100px) * .3); background: linear-gradient(color-mix(in srgb, var(--accent) 14%, transparent), color-mix(in srgb, var(--accent-2) 14%, transparent)); position: relative; overflow: hidden; }
.darma-loader-darma-b9-lava-lamp span { position: absolute; left: 50%; width: calc(var(--loader-size, 100px) * .42); height: calc(var(--loader-size, 100px) * .42); margin-left: calc(var(--loader-size, 100px) * -.21); border-radius: 50%; background: radial-gradient(circle at 40% 35%, color-mix(in srgb, #fff 30%, var(--accent)), var(--accent)); animation: darma-loader-darma-b9-lava-lamp-lava-a calc(var(--loader-speed, 1s) * 4) ease-in-out infinite; }
.darma-loader-darma-b9-lava-lamp span:nth-child(2) { width: calc(var(--loader-size, 100px) * .28); height: calc(var(--loader-size, 100px) * .28); margin-left: calc(var(--loader-size, 100px) * -.14); background: radial-gradient(circle at 40% 35%, color-mix(in srgb, #fff 30%, var(--accent-2)), var(--accent-2)); animation: darma-loader-darma-b9-lava-lamp-lava-b calc(var(--loader-speed, 1s) * 5) ease-in-out infinite; }
@keyframes darma-loader-darma-b9-lava-lamp-lava-a { 0%, 100% { bottom: -14%; border-radius: 50% 50% 44% 46%; } 50% { bottom: 76%; border-radius: 46% 44% 50% 48%; } }
@keyframes darma-loader-darma-b9-lava-lamp-lava-b { 0%, 100% { bottom: 72%; } 50% { bottom: -10%; } }

